import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { firstValueFrom, TimeoutError, timeout } from 'rxjs';
import { environment } from '../../../environments/environment';

export interface ExternalPgcrPartner {
  membershipId: string;
  displayName: string;
  activitiesTogether: number;
  timeTogetherSeconds: number;
  firstPlayedTogether?: string;
  lastPlayedTogether?: string;
  firstInstanceId?: string;
  lastInstanceId?: string;
  /** Split by the looked-up account (only accounts that shared at least one game). */
  perAccount?: PlayedWithPerAccount[];
}

export interface PlayedWithPerAccount {
  id: string;
  activitiesTogether: number;
  timeTogetherSeconds: number;
  firstPlayedTogether?: string;
  lastPlayedTogether?: string;
}

/** One looked-up account in a Played With response. */
export interface PlayedWithAccount {
  id: string;
  name: string | null;
  platform: string | null;
  game: 'D1' | 'D2';
  status: 'ready' | 'building' | 'queued' | string;
  refreshing?: boolean;
  included: boolean;
  games?: number;
  bungieGames?: number;
  d1Games?: number;
  position?: number | null;
  progress?: PlayedWithBuildProgress | null;
}

export interface PlayedWithCoverageInfo {
  complete?: boolean;
  games?: number;
  bungieGames?: number;
  d1GamesNotCounted?: number;
  accountsReady?: number;
  accountsIncluded?: number;
}

/** Result of POST /played-with/stats (summary hit or queued build). */
export interface PlayedWithApiResult {
  partners: ExternalPgcrPartner[];
  pending: boolean;
  queued?: boolean;
  status?: string;
  position?: number | null;
  source?: string;
  games?: number;
  /** Real counts from the server's summary worker while it builds (null when not started). */
  progress?: PlayedWithBuildProgress | null;
  /** Per-account status (server v2); empty for older servers. */
  accounts?: PlayedWithAccount[];
  /** Some included accounts are still building; partners cover the ready ones. */
  partial?: boolean;
  coverage?: PlayedWithCoverageInfo | null;
}

export interface PlayedWithBuildProgress {
  stage: 'loading_games' | 'scanning' | 'ranking' | 'bungie_history' | 'bungie_pgcrs';
  accountsLoaded: number;
  accountsTotal: number;
  games: number;
  batchesDone?: number;
  batchesTotal?: number;
  bungieGames?: number;
  pgcrsDone?: number;
  pgcrsTotal?: number;
  updatedAt?: string;
}

export interface LightActivityRow {
  instanceId: string;
  period: string;
  activityHash: string;
  mode: number;
  membershipId: string;
  membershipType: number;
  characterId: string;
  completed: number;
  deaths: number;
  kills: number;
  assists: number;
  durationSeconds: number;
  game: 'D1' | 'D2';
  displayName: string;
}

export interface PlayerActivitiesCoverage {
  level: 'full' | 'partial' | 'absent';
  source:
    | 'lite'
    | 'extract'
    | 'compact_ids'
    | 'gap_lean'
    | 'merged'
    | 'none'
    | 'pending'
    | 'archive';
  rowCount: number;
  distinctInstances?: number;
  minPeriod?: string | null;
  maxPeriod?: string | null;
  watermarkNote?: string;
  indexComplete?: boolean;
  filtersApplied?: boolean;
  notes?: string[];
  archiveCompleteBelowIid?: string;
}

export interface PlayerActivitiesResponse {
  membershipId: string;
  coverage: PlayerActivitiesCoverage;
  activities: LightActivityRow[];
  partialInstanceIds?: string[];
}

@Injectable({
  providedIn: 'root'
})
export class PgcrApiService {
  /** Dedupe concurrent cold-start character loads for the same mid+game. */
  private playerActivitiesInflight = new Map<string, Promise<PlayerActivitiesResponse | null>>();
  private playerActivitiesCache = new Map<string, PlayerActivitiesResponse | null>();

  constructor(private http: HttpClient) {}

  get enabled(): boolean {
    return environment.useExternalPgcr && !!environment.pgcrApiRoot?.trim();
  }

  /** Drop memoized player activity lists (e.g. after IDB wipe / new sync session). */
  clearPlayerActivitiesCache(): void {
    this.playerActivitiesCache.clear();
    this.playerActivitiesInflight.clear();
  }

  private headers(): HttpHeaders {
    const h: Record<string, string> = { 'Content-Type': 'application/json', 'X-DC-Client': 'web' };
    const key = environment.pgcrApiKey?.trim();
    if (key) {
      h['X-API-Key'] = key;
    }
    return new HttpHeaders(h);
  }

  private url(path: string): string {
    const root = environment.pgcrApiRoot.replace(/\/+$/, '');
    return `${root}${path.startsWith('/') ? path : `/${path}`}`;
  }

  /** Stable archive high-water mark. Not a per-account activity date. */
  async fetchWatermark(): Promise<{ max_instance_id: string; as_of: string } | null> {
    if (!this.enabled) {
      return null;
    }
    try {
      const body = await firstValueFrom(
        this.http.get<{ max_instance_id?: string; as_of?: string }>(
          this.url('/api/pgcr/watermark'),
          { headers: this.headers() }
        )
      );
      if (!body?.max_instance_id) {
        return null;
      }
      const instanceId = String(body.max_instance_id);
      let asOf = String(body.as_of || '');
      // Live watermark JSON has no as_of. The date is the period of that instance.
      if (!/^\d{4}-\d{2}-\d{2}/.test(asOf)) {
        const pgcr = await this.fetchPgcr(instanceId, 'D2') as { activityDetails?: { period?: string } } | null;
        const period = pgcr?.activityDetails?.period || '';
        if (/^\d{4}-\d{2}-\d{2}/.test(period)) {
          asOf = period;
        }
      }
      return {
        max_instance_id: instanceId,
        as_of: asOf,
      };
    } catch {
      return null;
    }
  }

  /**
   * Fetch one PGCR from the archive API.
   * @param opts.archiveOnly skip server-side Bungie (fast 404 on miss)
   * @param opts.timeoutMs abort the request after this many ms (null on timeout)
   */
  async fetchPgcr(
    instanceId: string,
    game: 'D1' | 'D2',
    opts?: { archiveOnly?: boolean; timeoutMs?: number }
  ): Promise<unknown | null> {
    if (!this.enabled) {
      return null;
    }
    const params: Record<string, string> = { game, format: 'lite' };
    if (opts?.archiveOnly) {
      params['source'] = 'archive';
    }
    const timeoutMs = opts?.timeoutMs ?? 0;
    try {
      const req$ = this.http.get(this.url(`/pgcr/${instanceId}`), {
        headers: this.headers(),
        params,
      });
      if (timeoutMs > 0) {
        try {
          return await firstValueFrom(req$.pipe(timeout({ first: timeoutMs })));
        } catch (err: unknown) {
          if (err instanceof TimeoutError || (err as { name?: string })?.name === 'TimeoutError') {
            return null;
          }
          const status = (err as { status?: number })?.status;
          if (status === 404) return null;
          throw err;
        }
      }
      return await firstValueFrom(req$);
    } catch (err: unknown) {
      const status = (err as { status?: number })?.status;
      if (status === 404) {
        return null;
      }
      throw err;
    }
  }

  async fetchPgcrBatch(instanceIds: string[], game: 'D1' | 'D2'): Promise<Map<string, unknown>> {
    const out = new Map<string, unknown>();
    if (!this.enabled || !instanceIds.length) {
      return out;
    }
    const chunkSize = 100;
    for (let i = 0; i < instanceIds.length; i += chunkSize) {
      const chunk = instanceIds.slice(i, i + chunkSize);
      try {
        const body = await firstValueFrom(
          this.http.post<Record<string, unknown>>(
            this.url('/pgcr/batch'),
            { instanceIds: chunk, game },
            { headers: this.headers(), params: { format: 'lite' } }
          )
        );
        for (const [id, pgcr] of Object.entries(body || {})) {
          if (pgcr) {
            out.set(id, pgcr);
          }
        }
      } catch {
        // Fall back to Bungie for this chunk
      }
    }
    return out;
  }

  async fetchPrunedPgcr(instanceId: string, game: 'D1' | 'D2'): Promise<unknown | null> {
    if (!this.enabled) {
      return null;
    }
    try {
      return await firstValueFrom(
        this.http.get(this.url(`/pgcr/${instanceId}`), {
          headers: this.headers(),
          params: { game, format: 'pruned' }
        })
      );
    } catch (err: unknown) {
      const status = (err as { status?: number })?.status;
      if (status === 404) {
        return null;
      }
      return null;
    }
  }

  async fetchPlayedWithStats(
    membershipIds: string[],
    opts: { include?: string[]; sortBy?: string } = {}
  ): Promise<PlayedWithApiResult | null> {
    if (!environment.enablePlayedWith) {
      return null;
    }
    if (!this.enabled || !membershipIds.length) {
      return null;
    }
    try {
      // 202 Accepted (pending build) is still a success body for HttpClient.
      const resp = await firstValueFrom(
        this.http.post<{
          partners?: ExternalPgcrPartner[];
          pending?: boolean;
          queued?: boolean;
          status?: string;
          position?: number | null;
          source?: string;
          games?: number;
          progress?: PlayedWithBuildProgress | null;
          accounts?: PlayedWithAccount[];
          partial?: boolean;
          coverage?: PlayedWithCoverageInfo | null;
        }>(
          this.url('/played-with/stats'),
          { membershipIds, include: opts.include, sortBy: opts.sortBy, limit: 500 },
          { headers: this.headers() }
        )
      );
      const pending = !!resp?.pending;
      return {
        partners: resp?.partners ?? [],
        pending,
        queued: resp?.queued,
        status: resp?.status,
        position: resp?.position ?? null,
        source: resp?.source,
        games: resp?.games,
        progress: resp?.progress ?? null,
        accounts: resp?.accounts ?? [],
        partial: !!resp?.partial,
        coverage: resp?.coverage ?? null
      };
    } catch {
      return null;
    }
  }

  /**
   * Fetch archived activity history for a single player from the local PGCR archive API.
   * Returns light activity rows (without full PGCR bodies) for fast cold-start loading.
   * Returns null if the API is disabled or the player has no archived data (404).
   * Throws on hard failures (5xx / network) so callers can surface a Bungie-fallback notice.
   */
  async fetchPlayerActivities(
    membershipId: string,
    options?: { game?: 'D1' | 'D2'; from?: string; to?: string; limit?: number }
  ): Promise<PlayerActivitiesResponse | null> {
    if (!this.enabled) {
      return null;
    }

    const cacheKey = [
      membershipId,
      options?.game ?? '',
      options?.from ?? '',
      options?.to ?? '',
      String(options?.limit ?? '')
    ].join('|');

    if (this.playerActivitiesCache.has(cacheKey)) {
      return this.playerActivitiesCache.get(cacheKey) ?? null;
    }
    const inflight = this.playerActivitiesInflight.get(cacheKey);
    if (inflight) {
      return inflight;
    }

    const request = (async (): Promise<PlayerActivitiesResponse | null> => {
      try {
        const params: Record<string, string> = {};
        if (options?.game) params['game'] = options.game;
        if (options?.from) params['from'] = options.from;
        if (options?.to) params['to'] = options.to;
        // Default high enough for PSN-scale histories (~7.4k); callers may override.
        params['limit'] = String(options?.limit ?? 10000);

        const response = await firstValueFrom(
          this.http.get<PlayerActivitiesResponse>(
            this.url(`/players/${membershipId}/activities`),
            { headers: this.headers(), params }
          )
        );
        this.playerActivitiesCache.set(cacheKey, response);
        return response;
      } catch (err: unknown) {
        const status = (err as { status?: number })?.status;
        if (status === 404) {
          // Player not in archive — expected miss; caller falls back without treating as outage.
          this.playerActivitiesCache.set(cacheKey, null);
          return null;
        }
        console.warn(`[Archive] fetchPlayerActivities failed for ${membershipId}:`, err);
        // Hard failure (5xx / network / etc.): rethrow so the UI can show Bungie-fallback notice.
        // Do not cache — allow retry on next character / sync.
        throw err;
      } finally {
        this.playerActivitiesInflight.delete(cacheKey);
      }
    })();

    this.playerActivitiesInflight.set(cacheKey, request);
    return request;
  }

  /**
   * Batch fetch archived activity history for multiple players.
   * More efficient than multiple individual requests when loading multiple accounts.
   */
  async fetchPlayerActivitiesBatch(
    membershipIds: string[]
  ): Promise<Map<string, PlayerActivitiesResponse>> {
    const result = new Map<string, PlayerActivitiesResponse>();
    if (!this.enabled || !membershipIds.length) {
      return result;
    }
    try {
      const response = await firstValueFrom(
        this.http.post<Record<string, PlayerActivitiesResponse>>(
          this.url('/players/activities/batch'),
          { membershipIds },
          { headers: this.headers() }
        )
      );
      for (const [membershipId, data] of Object.entries(response || {})) {
        if (data && data.coverage && data.activities) {
          result.set(membershipId, data);
        }
      }
      return result;
    } catch (err) {
      console.warn('[PgcrApiService] Failed to batch fetch player activities:', err);
      return result;
    }
  }
}

/** CODE_CLEANUP_SPEC name for Chronicle archive HTTP (same injectable). */
export { PgcrApiService as ArchiveApiService };
