export interface PlayerSearchResult {
  displayName: string;
  membershipType: number;
  membershipId: string;
  bungieGlobalDisplayName?: string;
  bungieGlobalDisplayNameCode?: string;
  isCrossSavePrimary?: boolean;
}

export interface BungieResponse<T> {
  Response: T;
  ErrorCode: number;
  ErrorStatus: string;
  Message: string;
  MessageData: { [key: string]: string };
}

interface BungieApiResponse<T> {
  ErrorCode: number;
  ErrorStatus: string;
  Message: string;
  MessageData: { [key: string]: string };
  Response: T;
  ThrottleSeconds: number;
}

interface ProfileRecordsResponse {
  data: {
    records: {
      [key: string]: {
        objectives: Array<{ complete: boolean }>;
        state: number;
      };
    };
  };
}

interface TitleRecord {
  completed: boolean;
  objectives?: Array<{
    complete: boolean;
    progress?: number;
    completionValue?: number;
  }>;
  state: number;
  completedCount?: number;
}

interface TitleResponse {
  profileRecords?: {
    data?: {
      records?: { [key: string]: TitleRecord }
    }
  };
  characterRecords?: {
    data?: {
      records?: { [key: string]: TitleRecord }
    }
  };
  // Add other fields if needed
}

